package com.witchersbestiary.test;
import com.witchersbestiary.signs.*;import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.test.*;import net.minecraft.entity.*;import net.minecraft.entity.mob.*;import net.minecraft.item.*;import net.minecraft.util.math.*;
public final class SignTests implements FabricGameTest {
 private net.minecraft.server.network.ServerPlayerEntity player(TestContext c){return player(c,true);}private net.minecraft.server.network.ServerPlayerEntity player(TestContext c,boolean trained){var data=net.minecraft.server.network.ConnectedClientData.createDefault(new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"sign"+java.util.UUID.randomUUID().toString().substring(0,8)),false);var p=new net.minecraft.server.network.ServerPlayerEntity(c.getWorld().getServer(),c.getWorld(),data.gameProfile(),data.syncedOptions());var connection=new net.minecraft.network.ClientConnection(net.minecraft.network.NetworkSide.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(connection);c.getWorld().getServer().getPlayerManager().onPlayerConnect(connection,p,data);p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);for(int i=0;i<61;i++)p.tick();p.setHealth(20);p.getHungerManager().setFoodLevel(10);p.setNoGravity(true);var pos=c.getAbsolutePos(new BlockPos(6,2,6));p.refreshPositionAndAngles(pos.getX()+.5,pos.getY(),pos.getZ()+.5,0,0);if(trained)for(var s:SignType.values())SignManager.state(p).learn(s);return p;}
 private ZombieEntity target(TestContext c,net.minecraft.server.network.ServerPlayerEntity p){var e=EntityType.ZOMBIE.create(c.getWorld());e.refreshPositionAndAngles(p.getX(),p.getY(),p.getZ()+3,180,0);e.setAiDisabled(true);e.setPersistent();e.setNoGravity(true);e.equipStack(EquipmentSlot.HEAD,new ItemStack(Items.CARVED_PUMPKIN));c.getWorld().spawnEntity(e);return e;}
 @GameTest(templateName="witchersbestiary:village_board_arena") public void resourceLearningSerializationAndReplay(TestContext c){var s=new SignPlayerState();c.assertTrue(!s.commit(SignType.IGNI,1),"Unlearned cast rejected");s.learn(SignType.IGNI);c.assertTrue(s.commit(SignType.IGNI,2)&&s.concentration()==70&&!s.commit(SignType.IGNI,2),"One payment, no replay");for(int i=0;i<70;i++)s.tick();c.assertTrue(s.concentration()==80&&s.cooldown(SignType.IGNI)==0,"Online-only delayed regeneration");var copy=SignPlayerState.read(s.write());c.assertTrue(copy.concentration()==80&&copy.knows(SignType.IGNI),"Save exact energy and learning");c.complete();}
 @GameTest(templateName="witchersbestiary:village_board_arena") public void igniDamagesButDoesNotProcSwordEnchantments(TestContext c){var p=player(c);var e=target(c,p);p.setHealth(10);var sword=new ItemStack(Items.DIAMOND_SWORD);var ench=c.getWorld().getRegistryManager().get(net.minecraft.registry.RegistryKeys.ENCHANTMENT);sword.addEnchantment(ench.entryOf(com.witchersbestiary.enchantment.SwordEnchantments.BLOOD),3);sword.addEnchantment(ench.entryOf(com.witchersbestiary.enchantment.SwordEnchantments.RUNIC),3);p.getInventory().setStack(0,sword);c.assertTrue(SignManager.cast(p,1)&&e.getHealth()<20&&e.isOnFire(),"Actual Igni damage and burning");c.assertTrue(p.getHealth()==10&&!sword.contains(com.witchersbestiary.enchantment.SwordEnchantments.RUNIC_STATE),"No sword healing or rune charge");p.discard();e.discard();c.complete();}
 @GameTest(templateName="witchersbestiary:village_board_arena") public void wallsBlockDirectedSigns(TestContext c){var p=player(c);var e=target(c,p);for(int x=-1;x<=1;x++)for(int y=0;y<4;y++)c.getWorld().setBlockState(p.getBlockPos().add(x,y,1),net.minecraft.block.Blocks.STONE.getDefaultState());SignManager.cast(p,1);c.assertTrue(e.getHealth()==20&&!e.isOnFire(),"No damage through solid wall");p.discard();e.discard();c.complete();}
 @GameTest(templateName="witchersbestiary:village_board_arena") public void aardImpulseAndQuenPool(TestContext c){var p=player(c);var e=target(c,p);SignManager.state(p).select(SignType.AARD);c.assertTrue(SignManager.cast(p,1)&&e.getVelocity().lengthSquared()>0,"Aard produces physical impulse");SignManager.state(p).select(SignType.QUEN);c.assertTrue(SignManager.cast(p,2),"Quen cast");var source=c.getWorld().getDamageSources().fall();c.assertTrue(SignManager.protect(p,source,5)==0&&SignManager.protect(p,source,5)==2,"Finite eight HP pool, no artificial healing");p.discard();e.discard();c.complete();}
 @GameTest(templateName="witchersbestiary:village_board_arena",tickLimit=120) public void axiiExpiresWithoutDeletingGoals(TestContext c){var p=player(c);var e=target(c,p);SignManager.state(p).select(SignType.AXII);c.assertTrue(SignManager.cast(p,1)&&SignManager.calmed(e),"Axii activated");c.runAtTick(90,()->{c.assertTrue(!SignManager.calmed(e),"Control naturally expired");p.discard();e.discard();c.complete();});}
 @GameTest(templateName="witchersbestiary:village_board_arena",tickLimit=50) public void yrdenSlowsHostileAndPreservesVillager(TestContext c){var p=player(c);c.getWorld().setBlockState(p.getBlockPos().down(),net.minecraft.block.Blocks.STONE.getDefaultState());var e=target(c,p);e.setPosition(p.getPos().add(1,0,0));var villager=EntityType.VILLAGER.create(c.getWorld());villager.refreshPositionAndAngles(p.getX()+1,p.getY(),p.getZ(),0,0);c.getWorld().spawnEntity(villager);SignManager.state(p).select(SignType.YRDEN);c.assertTrue(SignManager.cast(p,1),"Ground trap placed");c.runAtTick(20,()->{c.assertTrue(e.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS)&&!villager.hasStatusEffect(net.minecraft.entity.effect.StatusEffects.SLOWNESS),"Only hostile slowed");p.discard();e.discard();villager.discard();c.complete();});}
 @GameTest(templateName="witchersbestiary:village_board_arena") public void officialFistsRejectAllSignsWithoutPayment(TestContext c){var p=player(c);var npc=com.witchersbestiary.fist.FistRegistry.NOVICE.create(c.getWorld());npc.refreshPositionAndAngles(p.getX()+1,p.getY(),p.getZ(),0,0);c.getWorld().spawnEntity(npc);com.witchersbestiary.fist.FistFights.invite(p,npc);c.assertTrue(com.witchersbestiary.fist.FistFights.confirm(p,npc),"Official bout fixture");for(var sign:SignType.values()){SignManager.state(p).select(sign);c.assertTrue(!SignManager.cast(p,sign.ordinal()+1)&&SignManager.state(p).concentration()==100&&SignManager.state(p).cooldown(sign)==0,"No casts/payment/cooldowns in official fists "+sign);}com.witchersbestiary.fist.FistFights.cancel(p);p.discard();npc.discard();c.complete();}

 @GameTest(templateName="witchersbestiary:village_board_arena") public void quenAbsorbsActualDamageAndExhausts(TestContext c){var p=player(c);SignManager.state(p).select(SignType.QUEN);SignManager.cast(p,1);p.damage(c.getWorld().getDamageSources().generic(),5);c.assertTrue(p.getHealth()==20,"Actual damage absorbed before HP");p.timeUntilRegen=0;p.damage(c.getWorld().getDamageSources().generic(),5);c.assertTrue(p.getHealth()==18,"Only remaining three absorbed");p.timeUntilRegen=0;p.damage(c.getWorld().getDamageSources().generic(),2);c.assertTrue(p.getHealth()==16,"No permanent shield and no healing");p.discard();c.complete();}
 @GameTest(templateName="witchersbestiary:village_board_arena",tickLimit=60) public void yrdenExposesExistingSpectralResistance(TestContext c){var p=player(c);c.getWorld().setBlockState(p.getBlockPos().down(),net.minecraft.block.Blocks.STONE.getDefaultState());var e=com.witchersbestiary.entity.ModEntities.NOONWRAITH.create(c.getWorld());e.refreshPositionAndAngles(p.getX()+1,p.getY(),p.getZ(),0,0);e.setAiDisabled(true);e.setPersistent();e.setNoGravity(true);c.getWorld().spawnEntity(e);e.getAttributeInstance(net.minecraft.entity.attribute.EntityAttributes.GENERIC_MAX_HEALTH).setBaseValue(200);e.setHealth(200);float before=e.getHealth();e.damage(c.getWorld().getDamageSources().playerAttack(p),10);float baseline=before-e.getHealth();SignManager.state(p).select(SignType.YRDEN);SignManager.cast(p,1);c.runAtTick(20,()->{c.assertTrue(SignManager.yrdenExposed(e),"Specter exposed inside actual trap");e.timeUntilRegen=0;float hp=e.getHealth();e.damage(c.getWorld().getDamageSources().playerAttack(p),10);c.assertTrue(hp-e.getHealth()>baseline*1.5,"Existing physical resistance suspended, no stat modification");p.discard();e.discard();c.complete();});}

 @GameTest(templateName="witchersbestiary:village_board_arena",tickLimit=80) public void igniBurnKeepsContractKillAttribution(TestContext c){var p=player(c);var e=target(c,p);e.getAttributeInstance(net.minecraft.entity.attribute.EntityAttributes.GENERIC_ARMOR).setBaseValue(0);e.setHealth(5);var death=new java.util.concurrent.atomic.AtomicReference<net.minecraft.entity.damage.DamageSource>();net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents.AFTER_DEATH.register((entity,source)->{if(entity.getUuid().equals(e.getUuid()))death.set(source);});SignManager.cast(p,1);c.runAtTick(65,()->{c.assertTrue(!e.isAlive()&&death.get()!=null&&com.witchersbestiary.contracts.Contracts.killer(e,death.get())==p,"Actual burn finisher retains casting owner for existing contract credit");p.discard();e.discard();c.complete();});}
 @GameTest(templateName="witchersbestiary:village_board_arena") public void networkSessionDimensionReplayAndPlayerIsolation(TestContext c)throws Exception{var p=player(c);var other=player(c);var method=SignManager.class.getDeclaredMethod("runtime",net.minecraft.server.network.ServerPlayerEntity.class);method.setAccessible(true);var runtime=method.invoke(null,p);var field=runtime.getClass().getDeclaredField("session");field.setAccessible(true);var session=(java.util.UUID)field.get(runtime);String dimension=c.getWorld().getRegistryKey().getValue().toString();SignManager.intent(p,new SignPackets.Intent(java.util.UUID.randomUUID(),1,1,0,dimension));SignManager.intent(p,new SignPackets.Intent(session,2,1,0,"minecraft:the_nether"));c.assertTrue(SignManager.state(p).concentration()==100,"Invalid session/dimension cannot spend");var valid=new SignPackets.Intent(session,3,1,0,dimension);SignManager.intent(p,valid);SignManager.intent(p,valid);c.assertTrue(SignManager.state(p).concentration()==70&&SignManager.state(other).concentration()==100,"One payment, replay ignored, other player untouched");p.discard();other.discard();c.complete();}

 @GameTest(templateName="witchersbestiary:village_board_arena") public void signsFollowServerPvpRules(TestContext c){var p=player(c);var q=player(c);q.refreshPositionAndAngles(p.getX(),p.getY(),p.getZ()+3,180,0);boolean previous=p.getServer().isPvpEnabled();try{p.getServer().setPvpEnabled(false);SignManager.cast(p,1);c.assertTrue(q.getHealth()==20&&!q.isOnFire(),"pvp=false blocks all sign damage and burning");p.getServer().setPvpEnabled(true);c.assertTrue(SignManager.enemy(p,q),"Ordinary PvP eligibility restored");}finally{p.getServer().setPvpEnabled(previous);}p.discard();q.discard();c.complete();}

 @GameTest(templateName="witchersbestiary:village_board_arena") public void dimensionTransferClearsTransientEffectsBeforeNextTick(TestContext c)throws Exception{var p=player(c);c.getWorld().setBlockState(p.getBlockPos().down(),net.minecraft.block.Blocks.STONE.getDefaultState());SignManager.state(p).select(SignType.QUEN);SignManager.cast(p,1);SignManager.state(p).select(SignType.YRDEN);SignManager.cast(p,2);var nether=p.getServer().getWorld(net.minecraft.world.World.NETHER);nether.getChunk(0,0);p.teleport(nether,.5,130,.5,0,0);var method=SignManager.class.getDeclaredMethod("runtime",net.minecraft.server.network.ServerPlayerEntity.class);method.setAccessible(true);var runtime=method.invoke(null,p);var shield=runtime.getClass().getDeclaredField("shield");var trap=runtime.getClass().getDeclaredField("trapTicks");shield.setAccessible(true);trap.setAccessible(true);c.assertTrue(shield.getFloat(runtime)==0&&trap.getInt(runtime)==0,"Old dimension shield/trap cannot leak even before the next server tick");c.assertTrue(SignManager.state(p).concentration()==25&&SignManager.state(p).cooldown(SignType.QUEN)==160,"Persistent resource/cooldowns unchanged by transfer");p.discard();c.complete();}

 @GameTest(templateName="witchersbestiary:village_board_arena") public void deathRespawnPreservesLearningAndResourceWithoutShield(TestContext c)throws Exception{var p=player(c);SignManager.state(p).select(SignType.QUEN);SignManager.cast(p,1);var server=p.getServer();p.damage(c.getWorld().getDamageSources().outOfWorld(),10000);c.assertTrue(!p.isAlive(),"Actual player death");var replacement=server.getPlayerManager().respawnPlayer(p,false,Entity.RemovalReason.KILLED);var saved=SignManager.state(replacement);c.assertTrue(saved.learned()==31&&saved.selected()==SignType.QUEN&&saved.concentration()==60&&saved.cooldown(SignType.QUEN)==160,"Death cannot grant free resource or reset learned progress/cooldown");var method=SignManager.class.getDeclaredMethod("runtime",net.minecraft.server.network.ServerPlayerEntity.class);method.setAccessible(true);var runtime=method.invoke(null,replacement);var field=runtime.getClass().getDeclaredField("shield");field.setAccessible(true);c.assertTrue(field.getFloat(runtime)==0,"Dead body shield cannot transfer to replacement player");replacement.discard();c.complete();}

 @GameTest(templateName="witchersbestiary:village_board_arena") public void bestiaryLearningIsFreeIdempotentAndPersonal(TestContext c){var p=player(c,false);var q=player(c,false);c.assertTrue(!SignManager.learnFromBestiary(p,SignType.IGNI)&&SignManager.state(p).learned()==0,"Forged learning without existing bestiary rejected");p.getInventory().setStack(0,new ItemStack(com.witchersbestiary.registry.ModItems.BESTIARY));String inventory=p.getInventory().writeNbt(new net.minecraft.nbt.NbtList()).toString();int xp=p.totalExperience;for(var sign:SignType.values()){c.assertTrue(SignManager.learnFromBestiary(p,sign),"Existing book learns any basic sign");SignManager.learnFromBestiary(p,sign);}c.assertTrue(SignManager.state(p).learned()==31&&SignManager.state(q).learned()==0,"Single ledger, idempotence and independent players");c.assertTrue(SignManager.state(p).concentration()==100&&p.totalExperience==xp&&inventory.equals(p.getInventory().writeNbt(new net.minecraft.nbt.NbtList()).toString()),"No ingredients/crowns/XP/resource consumed");q.getInventory().setStack(0,new ItemStack(com.witchersbestiary.registry.ModItems.BESTIARY));SignManager.learnFromBestiary(q,SignType.AARD);c.assertTrue(SignManager.state(q).learned()==2&&SignManager.state(p).learned()==31,"Player B can learn different signs independently");p.discard();q.discard();c.complete();}

}
